+            group.add(v);
+            cg.addLocalVar(v);
+        }
+
+        // Make each closure, its siblings left null for now.
+        List<String> classNames = new ArrayList<String>(n);
+        List<List<VarCodeGen>> siblings = new ArrayList<List<VarCodeGen>>(n);
+        for (int i = 0; i < n; i++) {
+            List<VarCodeGen> sibs = new ArrayList<VarCodeGen>();
